def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.55))
        return float(min(budget, DAILY_SALARY * 0.25))

    prev_bids = []
    threat_score = 0.0
    cindy_bid = None
    bob_bid = None

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            req = opp.get('water_requirement', WATER_REQ)
            sal = opp.get('daily_salary', DAILY_SALARY)
            pressure = float(bid) / max(1.0, float(sal))
            if req <= supply:
                threat_score += pressure
            if opp.get('daily_salary') == 70 and opp.get('water_requirement') == 13:
                pass
        opp_prev_name_hint = opp.get('previous_trace', {})
        _ = opp_prev_name_hint

    for opp_id, opp in opponents_status.items():
        if not opp.get('alive'):
            continue
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if opp_id == 'Cindy' and bid is not None:
            cindy_bid = float(bid)
        if opp_id == 'Bob' and bid is not None:
            bob_bid = float(bid)

    contested = supply < (len(alive_opponents) + 1) * WATER_REQ
    very_tight = supply < 2 * WATER_REQ

    if hp <= 2 or no_water_days >= 2:
        emergency = max(0.92 * DAILY_SALARY, (max(prev_bids) + 2.0) if prev_bids else 64.0)
        if cindy_bid is not None:
            emergency = max(emergency, min(165.0, cindy_bid + 3.0))
        return float(min(budget, emergency))

    if hp <= 4 or no_water_days >= 1:
        if contested:
            target = 0.78 * DAILY_SALARY
            if prev_bids:
                target = max(target, max(prev_bids) + 1.5)
            if cindy_bid is not None and cindy_bid <= 90:
                target = max(target, cindy_bid + 2.0)
            return float(min(budget, target))
        return float(min(budget, 0.48 * DAILY_SALARY))

    if very_tight:
        if cindy_bid is not None and cindy_bid >= 95:
            return float(min(budget, 8.0))
        if prev_bids:
            top = max(prev_bids)
            if top < 70:
                return float(min(budget, top + 1.0))
        return float(min(budget, 18.0))

    if contested:
        if cindy_bid is not None and cindy_bid >= 110:
            return float(min(budget, 12.0))
        if bob_bid is not None and cindy_bid is None:
            return float(min(budget, max(32.0, bob_bid + 1.0)))
        if prev_bids:
            top = max(prev_bids)
            if top <= 60:
                return float(min(budget, top + 1.0))
            if top <= 80:
                return float(min(budget, 46.0))
        return float(min(budget, 28.0))

    return float(min(budget, 17.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        # Conservative if no opponents
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids to infer who is applying pressure
    cindy_y = None
    max_prev_bid = 0.0
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
            except Exception:
                b = 0.0
            if b > max_prev_bid:
                max_prev_bid = b
            if oid == 'Cindy':
                cindy_y = b

    # Determine how many allocations we likely need given supply
    # Approximate probability/urgency: if supply is low, bidding more helps secure water.
    # Use a simple urgency score.
    if supply <= WATER_REQ:
        urgency = 1.0
    else:
        # scale between 0.2..1.0 over supply range
        urgency = 0.2 + 0.8 * ((supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)) if MAX_SUPPLY != MIN_SUPPLY else 0.6
    urgency = max(0.2, min(1.0, urgency))

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # If we're already in danger, bid aggressively.
    danger = 1.0 if (hp <= 2.0 or no_water_days >= 2) else (0.6 if hp <= 4.0 else 0.2)

    # Base bid aimed to compete with Cindy's pressure.
    # If Cindy bid yesterday was very high, slightly undercut her; otherwise, bid mid-high.
    if cindy_y is not None and cindy_y > 0:
        if cindy_y >= DAILY_SALARY * 0.95:
            target = cindy_y - 5.0
        elif cindy_y >= DAILY_SALARY * 0.8:
            target = cindy_y - 10.0
        else:
            target = max(DAILY_SALARY * 0.55, cindy_y * 0.75)
    else:
        # Use max_prev_bid to infer general pressure
        if max_prev_bid >= DAILY_SALARY * 0.9:
            target = max_prev_bid - 8.0
        else:
            target = max(DAILY_SALARY * 0.5, max_prev_bid * 0.6)

    # Adjust for urgency and danger: bid more when supply is low or HP is critical.
    target = target * (0.75 + 0.5 * urgency) * (0.85 + 0.3 * danger)

    # Safety caps: never exceed budget and avoid wasting too much
    # Also keep within plausible bidding range
    cap = min(budget, DAILY_SALARY * 1.2)
    floor = 0.0

    bid = float(max(floor, min(cap, target)))

    # If budget is tiny, bid whatever we can.
    if bid <= 0.0 and budget > 0.0:
        bid = float(min(budget, DAILY_SALARY * 0.3))

    return bid
